BEGIN;
CREATE TEMP TABLE connection_test(child_a uuid,child_b uuid,circle_a uuid,circle_b uuid,request uuid,inv uuid,token text);
INSERT INTO connection_test DEFAULT VALUES;
GRANT ALL ON connection_test TO authenticated,anon,service_role;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"4180925a-80f5-443d-aed7-9792e5e96172","role":"authenticated"}',true);
UPDATE connection_test SET child_a=public.bts_save_profile('{"credit_name":"Connection Child A","date_of_birth":"2014-01-01","relationship_kind":"child","guardian_name":"Parent A"}',NULL,true),child_b=public.bts_save_profile('{"credit_name":"Private Sibling","date_of_birth":"2015-01-01","relationship_kind":"child","guardian_name":"Parent A"}',NULL,true);
UPDATE connection_test SET circle_a=(public.bts_circle('create_circle','{"name":"Creator Circle"}')->>'id')::uuid;
SELECT public.bts_circle('connect_profile',jsonb_build_object('circle_id',circle_a,'profile_id',child_a)) FROM connection_test;
SELECT public.bts_circle('connect_profile',jsonb_build_object('circle_id',circle_a,'profile_id',child_b)) FROM connection_test;
SELECT set_config('request.jwt.claims','{"sub":"3f6513e6-1dfc-48ae-991f-e889305bb4d6","role":"authenticated"}',true);
UPDATE connection_test SET circle_b=(public.bts_circle('create_circle','{"name":"Requester Circle"}')->>'id')::uuid;
UPDATE connection_test SET request=(public.bts_circle('request_access',jsonb_build_object('circle_id',circle_b,'email','team-creative@example.invalid','message','Please let me help with our child.'))->>'id')::uuid;
DO $$ BEGIN IF public.bts_profile_access((SELECT child_a FROM connection_test)) OR public.bts_circle('snapshot')::text LIKE '%Private Sibling%' THEN RAISE EXCEPTION 'TEST FAILED: request granted access or exposed profiles';END IF;END $$;
SELECT set_config('request.jwt.claims','{"sub":"131ad1e8-23b0-4756-81ce-bf59302e4b4f","role":"authenticated"}',true);
DO $$ BEGIN
 IF jsonb_array_length(public.bts_circle('snapshot')->'access_requests')<>0 THEN RAISE EXCEPTION 'TEST FAILED: request inbox exposed';END IF;
 BEGIN PERFORM public.bts_circle('respond_request',(SELECT jsonb_build_object('id',request,'approve',true,'profile_ids',jsonb_build_array(child_a)) FROM connection_test));RAISE EXCEPTION 'TEST FAILED: outsider approved request';EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'TEST FAILED:%' THEN RAISE;END IF;END;
END $$;
SELECT set_config('request.jwt.claims','{"sub":"4180925a-80f5-443d-aed7-9792e5e96172","role":"authenticated"}',true);
DO $$ BEGIN IF jsonb_array_length(public.bts_circle('snapshot')->'access_requests')<>1 THEN RAISE EXCEPTION 'TEST FAILED: recipient notification missing';END IF;END $$;
SELECT public.bts_circle('respond_request',jsonb_build_object('id',request,'approve',true,'profile_ids',jsonb_build_array(child_a))) FROM connection_test;
RESET ROLE;
UPDATE connection_test SET inv=(SELECT invitation_ids[1] FROM bts_private.circle_access_requests WHERE id=connection_test.request);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"3f6513e6-1dfc-48ae-991f-e889305bb4d6","role":"authenticated"}',true);
DO $$ BEGIN IF public.bts_profile_access((SELECT child_a FROM connection_test)) THEN RAISE EXCEPTION 'TEST FAILED: approval alone granted permission';END IF;IF jsonb_array_length(public.bts_circle('snapshot')->'incoming')<>1 OR public.bts_circle('snapshot')::text LIKE '%token_hash%' THEN RAISE EXCEPTION 'TEST FAILED: incoming invitation missing or token exposed';END IF;END $$;
SELECT public.bts_circle('accept_notice',jsonb_build_object('id',inv,'confirmed',true,'guardian_confirmed',true,'name','Parent B')) FROM connection_test;
DO $$ BEGIN
 IF NOT public.bts_profile_access((SELECT child_a FROM connection_test)) OR public.bts_profile_access((SELECT child_b FROM connection_test)) THEN RAISE EXCEPTION 'TEST FAILED: selected child scope';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.bts_circle('snapshot')->'circles') c WHERE c->>'name'='Requester Circle' AND (c->'profiles') @> (SELECT jsonb_build_array(child_a) FROM connection_test)) THEN RAISE EXCEPTION 'TEST FAILED: accepted member not connected';END IF;
 IF public.bts_circle('member_access',(SELECT jsonb_build_object('profile_id',child_a) FROM connection_test))::text LIKE '%@%' THEN RAISE EXCEPTION 'TEST FAILED: other parent email leaked';END IF;
 BEGIN PERFORM public.bts_circle('accept_notice',(SELECT jsonb_build_object('id',inv,'confirmed',true,'guardian_confirmed',true,'name','Parent B') FROM connection_test));RAISE EXCEPTION 'TEST FAILED: invitation replay';EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'TEST FAILED:%' THEN RAISE;END IF;END;
END $$;
SELECT set_config('request.jwt.claims','{"sub":"4180925a-80f5-443d-aed7-9792e5e96172","role":"authenticated"}',true);
UPDATE connection_test SET inv=(public.bts_circle('invite_admin',jsonb_build_object('circle_id',circle_a,'email','team-outsider@example.invalid','profile_ids',jsonb_build_array(child_a)))->>'id')::uuid;
SELECT set_config('request.jwt.claims','{"sub":"3f6513e6-1dfc-48ae-991f-e889305bb4d6","role":"authenticated"}',true);
DO $$ BEGIN BEGIN PERFORM public.bts_circle('decline_notice',(SELECT jsonb_build_object('id',inv) FROM connection_test));RAISE EXCEPTION 'TEST FAILED: wrong recipient declined';EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'TEST FAILED:%' THEN RAISE;END IF;END;END $$;
SELECT set_config('request.jwt.claims','{"sub":"131ad1e8-23b0-4756-81ce-bf59302e4b4f","role":"authenticated"}',true);
SELECT public.bts_circle('decline_notice',jsonb_build_object('id',inv)) FROM connection_test;
DO $$ BEGIN IF public.bts_profile_access((SELECT child_a FROM connection_test)) THEN RAISE EXCEPTION 'TEST FAILED: decline granted access';END IF;END $$;
SELECT set_config('request.jwt.claims','{"sub":"3f6513e6-1dfc-48ae-991f-e889305bb4d6","role":"authenticated"}',true);
UPDATE connection_test SET request=(public.bts_circle('request_access',jsonb_build_object('circle_id',circle_b,'email','team-outsider@example.invalid'))->>'id')::uuid;
SELECT public.bts_circle('cancel_request',jsonb_build_object('id',request)) FROM connection_test;
SELECT set_config('request.jwt.claims','{"sub":"131ad1e8-23b0-4756-81ce-bf59302e4b4f","role":"authenticated"}',true);
DO $$ BEGIN
 IF jsonb_array_length(public.bts_circle('snapshot')->'access_requests')<>0 THEN RAISE EXCEPTION 'TEST FAILED: cancelled request remained in recipient inbox';END IF;
 BEGIN PERFORM public.bts_circle('respond_request',(SELECT jsonb_build_object('id',request,'approve',true,'profile_ids',jsonb_build_array(child_a)) FROM connection_test));RAISE EXCEPTION 'TEST FAILED: cancelled request approved';EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'TEST FAILED:%' THEN RAISE;END IF;END;
END $$;
SELECT set_config('request.jwt.claims','{"sub":"4180925a-80f5-443d-aed7-9792e5e96172","role":"authenticated"}',true);
UPDATE connection_test SET inv=(public.bts_circle('invite_admin',jsonb_build_object('circle_id',circle_a,'email','circle-new@example.invalid','profile_ids',jsonb_build_array(child_a)))->>'id')::uuid;
RESET ROLE;
UPDATE connection_test t SET token=m.payload->>'token' FROM bts_private.family_mail m WHERE m.payload->>'invite_id'=t.inv::text;
DO $$ DECLARE meta jsonb;BEGIN
 SELECT jsonb_build_object('date_of_birth','1990-01-01','privacy_accepted',true,'terms_accepted',true,'beta_code',token) INTO meta FROM connection_test;
 BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES('ee2291d3-1043-4cd1-94dd-c410939a0011','wrong-circle-email@example.invalid',meta);RAISE EXCEPTION 'TEST FAILED: wrong email used circle signup';EXCEPTION WHEN raise_exception THEN IF SQLERRM LIKE 'TEST FAILED:%' THEN RAISE;END IF;END;
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES('ee2291d3-1043-4cd1-94dd-c410939a0012','circle-new@example.invalid',meta);
 IF EXISTS(SELECT 1 FROM auth.users WHERE id='ee2291d3-1043-4cd1-94dd-c410939a0012' AND raw_user_meta_data ? 'beta_code') THEN RAISE EXCEPTION 'TEST FAILED: invitation token retained in account metadata';END IF;
END $$;
SELECT 'PASS: circle connection checks' AS result;
ROLLBACK;
